{{-- Static newsroom post editor. Backend binding and save actions will be added later. --}}
<style>
.post-editor{--p:#4f5fe7;--line:#dfe4f1;--muted:#7b849b}.post-editor .page-header{align-items:center}.post-card{border:1px solid var(--line);border-radius:14px;box-shadow:0 7px 22px rgba(20,28,58,.05);overflow:hidden}.post-card .card-header{padding:1rem 1.15rem;background:rgba(79,95,231,.035);border-bottom:1px solid var(--line)}.post-heading{display:flex;align-items:center;gap:.65rem;margin:0;font-weight:700}.post-step{display:grid;place-items:center;width:30px;height:30px;color:#fff;background:var(--p);border-radius:9px;font-size:.75rem}.post-editor .form-label{font-weight:600}.hint{display:block;margin-top:.3rem;color:var(--muted);font-size:.75rem}.counter{float:right;color:var(--muted);font-size:.72rem;font-weight:400}.post-title{min-height:50px;font-size:1.08rem;font-weight:600}.editor-tools{display:flex;flex-wrap:wrap;gap:.35rem;padding:.6rem;border:1px solid var(--line);border-bottom:0;border-radius:9px 9px 0 0;background:#f8f9fc}.editor-tools button{height:30px;min-width:32px;border:1px solid #d9deea;border-radius:6px;background:#fff}.story-body{min-height:350px;border-radius:0 0 9px 9px!important;line-height:1.8}.upload-box{display:flex;align-items:center;justify-content:center;min-height:185px;padding:1.2rem;text-align:center;border:2px dashed #c9d0e5;border-radius:11px;background:#fafbff;cursor:pointer}.upload-box:hover{border-color:var(--p)}.upload-icon{display:grid;place-items:center;width:50px;height:50px;margin:0 auto .7rem;color:var(--p);background:#e9ebff;border-radius:14px}.image-preview{width:100%;max-height:230px;object-fit:cover;border-radius:9px}.gallery-row{display:grid;grid-template-columns:44px 1fr 1fr 38px;gap:.55rem;align-items:center;padding:.55rem;border:1px solid var(--line);border-radius:9px}.gallery-icon{display:grid;place-items:center;width:44px;height:44px;color:var(--p);background:#edf0ff;border-radius:8px}.switch-row{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:.75rem 0;border-bottom:1px dashed var(--line)}.placement-grid{display:grid;grid-template-columns:1fr 1fr;gap:.5rem}.placement{position:relative}.placement input{position:absolute;opacity:0}.placement label{display:block;margin:0;padding:.6rem;border:1px solid var(--line);border-radius:8px;text-align:center;cursor:pointer;font-size:.78rem}.placement input:checked+label{color:var(--p);border-color:var(--p);background:#f0f2ff;font-weight:700}.seo-preview{padding:1rem;border:1px solid var(--line);border-radius:10px}.seo-title{color:#1a0dab;font-size:1.08rem}.seo-url{color:#188038;font-size:.78rem}.save-bar{position:sticky;bottom:0;z-index:8;display:flex;align-items:center;justify-content:space-between;gap:1rem;margin-top:1rem;padding:.85rem 1rem;border:1px solid var(--line);border-radius:12px;background:rgba(255,255,255,.96);box-shadow:0 -7px 22px rgba(20,28,58,.08)}.post-modal .modal-dialog{max-width:1180px;height:calc(100vh - 2rem);margin:1rem auto}.post-modal .modal-content{height:100%;overflow:hidden;border:1px solid var(--line);border-radius:16px}.post-modal form{display:flex;flex-direction:column;height:100%;min-height:0}.post-modal .post-modal-body{flex:1;min-height:0;padding:1.25rem;overflow-y:auto;overscroll-behavior:contain}.post-modal .modal-header,.post-modal .modal-footer{flex:0 0 auto}.post-stat{display:flex;align-items:center;gap:1rem;min-height:98px}.post-stat-icon{display:grid;place-items:center;width:52px;height:52px;border-radius:14px;font-size:1.25rem}.post-list-thumb{width:48px;height:42px;object-fit:cover;border-radius:9px;background:#e9edfa}.post-list-placeholder{display:grid;place-items:center;color:var(--p)}@media(min-width:1200px){.sticky-side{position:relative}}@media(max-width:767px){.gallery-row{grid-template-columns:38px 1fr 36px}.gallery-caption{grid-column:2/4}.save-bar{align-items:stretch;flex-direction:column}.save-actions{display:grid!important;grid-template-columns:1fr 1fr}}
</style>
<div class="app-content main-content post-editor"><div class="side-app"><div class="container-fluid main-container">
<div class="page-header"><div class="page-leftheader"><div class="mb-1"><span class="badge bg-primary-transparent text-primary">Newsroom</span> <span class="text-muted small">Content management</span></div><h4 class="page-title mb-1">News Posts</h4><p class="text-muted mb-0">Create, review and manage newsroom stories.</p></div><div class="ms-auto"><button type="button" class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#post-form-modal"><i class="fe fe-plus me-1"></i>Create Post</button></div></div>

{{-- Static overview follows the same list-then-modal pattern as the Poll module. --}}
<div class="row g-3 mb-4">
<div class="col-xl-3 col-sm-6"><div class="card post-card mb-0"><div class="card-body post-stat"><span class="post-stat-icon bg-primary-transparent text-primary"><i class="fe fe-file-text"></i></span><span><span class="text-muted">Total Posts</span><strong class="d-block fs-4">248</strong></span></div></div></div>
<div class="col-xl-3 col-sm-6"><div class="card post-card mb-0"><div class="card-body post-stat"><span class="post-stat-icon bg-success-transparent text-success"><i class="fe fe-check-circle"></i></span><span><span class="text-muted">Published</span><strong class="d-block fs-4">186</strong></span></div></div></div>
<div class="col-xl-3 col-sm-6"><div class="card post-card mb-0"><div class="card-body post-stat"><span class="post-stat-icon bg-warning-transparent text-warning"><i class="fe fe-edit-3"></i></span><span><span class="text-muted">Draft & Review</span><strong class="d-block fs-4">47</strong></span></div></div></div>
<div class="col-xl-3 col-sm-6"><div class="card post-card mb-0"><div class="card-body post-stat"><span class="post-stat-icon bg-info-transparent text-info"><i class="fe fe-calendar"></i></span><span><span class="text-muted">Scheduled</span><strong class="d-block fs-4">15</strong></span></div></div></div>
</div>
<div class="card post-card mb-4"><div class="card-body"><div class="row g-3 align-items-end"><div class="col-lg-5"><label class="form-label">Search post</label><div class="input-group"><span class="input-group-text"><i class="fe fe-search"></i></span><input class="form-control" placeholder="Search by headline..."></div></div><div class="col-md-3"><label class="form-label">Status</label><select class="form-select"><option>All statuses</option><option>Published</option><option>Draft</option><option>Review</option><option>Scheduled</option></select></div><div class="col-md-3"><label class="form-label">Category</label><select class="form-select"><option>All categories</option><option>National</option><option>Politics</option><option>Sports</option></select></div><div class="col-lg-1"><button type="button" class="btn btn-outline-primary w-100"><i class="fe fe-filter"></i></button></div></div></div></div>
<div class="card post-card"><div class="card-header d-flex justify-content-between align-items-center"><h5 class="mb-0">Post List</h5><span class="text-muted small">3 sample posts</span></div><div class="card-body p-0"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Post</th><th>Category</th><th>Author</th><th>Published</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody>
<tr><td><div class="d-flex align-items-center gap-2"><span class="post-list-thumb post-list-placeholder"><i class="fe fe-image"></i></span><span><strong class="d-block">জাতীয় নির্বাচনের প্রস্তুতি নিয়ে সর্বশেষ খবর</strong><small class="text-muted">/news/national-election-update</small></span></div></td><td>National</td><td>Sumon Mitra</td><td>24 Aug 2026</td><td><span class="badge bg-success-transparent text-success">Published</span></td><td class="text-end"><button class="btn btn-sm btn-outline-primary" type="button"><i class="fe fe-edit-2"></i></button> <button class="btn btn-sm btn-outline-danger" type="button"><i class="fe fe-trash-2"></i></button></td></tr>
<tr><td><div class="d-flex align-items-center gap-2"><span class="post-list-thumb post-list-placeholder"><i class="fe fe-image"></i></span><span><strong class="d-block">অর্থনীতির নতুন সম্ভাবনা ও চ্যালেঞ্জ</strong><small class="text-muted">/news/economy-opportunities</small></span></div></td><td>Economy</td><td>News Desk</td><td>—</td><td><span class="badge bg-warning-transparent text-warning">Draft</span></td><td class="text-end"><button class="btn btn-sm btn-outline-primary" type="button"><i class="fe fe-edit-2"></i></button> <button class="btn btn-sm btn-outline-danger" type="button"><i class="fe fe-trash-2"></i></button></td></tr>
<tr><td><div class="d-flex align-items-center gap-2"><span class="post-list-thumb post-list-placeholder"><i class="fe fe-video"></i></span><span><strong class="d-block">বাংলাদেশ দলের সামনে গুরুত্বপূর্ণ ম্যাচ</strong><small class="text-muted">/sports/bangladesh-important-match</small></span></div></td><td>Sports</td><td>Sports Desk</td><td>25 Aug 2026</td><td><span class="badge bg-info-transparent text-info">Scheduled</span></td><td class="text-end"><button class="btn btn-sm btn-outline-primary" type="button"><i class="fe fe-edit-2"></i></button> <button class="btn btn-sm btn-outline-danger" type="button"><i class="fe fe-trash-2"></i></button></td></tr>
</tbody></table></div></div><div class="card-footer d-flex justify-content-between"><span class="text-muted small">Showing 1 to 3 of 3</span><nav><ul class="pagination pagination-sm mb-0"><li class="page-item disabled"><span class="page-link">Previous</span></li><li class="page-item active"><span class="page-link">1</span></li><li class="page-item disabled"><span class="page-link">Next</span></li></ul></nav></div></div>

{{-- The large editor opens in a viewport-height, internally scrollable modal. --}}
<div class="modal fade post-modal" id="post-form-modal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content">
<form id="post-editor-form" action="javascript:void(0)" enctype="multipart/form-data">@csrf
<div class="modal-header"><div><h5 class="modal-title mb-1">Create New Post</h5><p class="text-muted small mb-0">Write the story, add media and configure publishing.</p></div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div>
<div class="post-modal-body"><div class="row g-4"><div class="col-xl-8">
<div class="card post-card"><div class="card-header"><h5 class="post-heading"><span class="post-step">01</span>Story information</h5></div><div class="card-body"><div class="row g-3">
<div class="col-md-4"><label class="form-label">Post type *</label><select name="post_type" class="form-select"><option value="news">News</option><option value="article">Article</option><option value="opinion">Opinion</option><option value="video">Video</option><option value="photo_story">Photo story</option></select></div>
<div class="col-md-8"><label class="form-label">Special title</label><input name="special_title" class="form-control" placeholder="Exclusive, Analysis or Breaking"></div>
<div class="col-12"><label class="form-label">Headline * <span class="counter"><b data-title-count>0</b>/255</span></label><input id="post-title" name="title" maxlength="255" class="form-control post-title" placeholder="Write a clear and compelling headline"></div>
<div class="col-12"><label class="form-label">URL slug</label><div class="input-group"><span class="input-group-text">/news/</span><input id="post-slug" name="slug" class="form-control" placeholder="news-headline"><button type="button" id="make-post-slug" class="btn btn-outline-primary">Generate</button></div></div>
<div class="col-12"><label class="form-label">Summary <span class="counter"><b data-summary-count>0</b>/500</span></label><textarea id="post-summary" name="summary" maxlength="500" rows="4" class="form-control" placeholder="Give readers a short overview"></textarea></div>
</div></div></div>
<div class="card post-card"><div class="card-header"><h5 class="post-heading"><span class="post-step">02</span>Story content</h5></div><div class="card-body">
<div class="editor-tools"><button type="button">H</button><button type="button"><b>B</b></button><button type="button"><i>I</i></button><button type="button">“ ”</button><button type="button">☷</button><button type="button">↗</button><button type="button">▧</button><button type="button">▶</button></div>
<textarea name="description" class="form-control story-body" placeholder="Write the full news story here..."></textarea><div class="d-flex justify-content-between mt-2 text-muted small"><span>Rich-text editor will be connected later.</span><span>Words: <b data-word-count>0</b> · <b data-read-time>0 min</b></span></div>
</div></div><div class="card post-card"><div class="card-header"><h5 class="post-heading"><span class="post-step">03</span>Media</h5></div><div class="card-body"><div class="row g-3">
<div class="col-lg-6"><label class="form-label">Featured image</label><label class="upload-box" for="post-featured-image"><span data-upload-text><span class="upload-icon"><i class="fe fe-image"></i></span><strong>Choose cover image</strong><span class="hint">JPG, PNG or WebP · 1200×675 recommended</span></span><img class="image-preview d-none" data-image-preview alt="Preview"></label><input type="file" id="post-featured-image" name="featured_image" class="d-none" accept="image/jpeg,image/png,image/webp"></div>
<div class="col-lg-6"><label class="form-label">Image caption</label><textarea name="image_caption" rows="3" class="form-control mb-3" placeholder="Image context and caption"></textarea><label class="form-label">Image alt text</label><input name="image_alt" class="form-control" placeholder="Accessible image description"></div>
<div class="col-md-4"><label class="form-label">Video type</label><select name="video_type" class="form-select"><option value="">No video</option><option value="youtube">YouTube</option><option value="facebook">Facebook</option><option value="vimeo">Vimeo</option><option value="upload">Upload</option></select></div>
<div class="col-md-8"><label class="form-label">Video URL</label><input type="url" name="video_url" class="form-control" placeholder="https://..."></div><div class="col-12"><hr>
<div class="d-flex justify-content-between align-items-center mb-3"><div><h6 class="mb-1">Story gallery</h6><span class="text-muted small">Supporting photographs in display order.</span></div><button type="button" id="add-gallery" class="btn btn-sm btn-outline-primary"><i class="fe fe-plus"></i> Add image</button></div>
<div id="gallery-list" class="d-grid gap-2"><div class="gallery-row"><span class="gallery-icon"><i class="fe fe-image"></i></span><input type="file" name="gallery_images[]" class="form-control form-control-sm" accept="image/*"><input name="gallery_captions[]" class="form-control form-control-sm gallery-caption" placeholder="Caption"><button type="button" class="btn btn-sm btn-outline-danger remove-gallery"><i class="fe fe-trash-2"></i></button></div></div>
</div></div></div></div>
<div class="card post-card"><div class="card-header"><h5 class="post-heading"><span class="post-step">04</span>SEO & social preview</h5></div><div class="card-body">
<div class="seo-preview mb-4"><div class="seo-title" data-seo-title>Your news headline will appear here</div><div class="seo-url">https://example.com/news/<span data-seo-slug>news-headline</span></div><p class="mb-0 mt-1 text-muted small" data-seo-description>Add a concise meta description for search results.</p></div>
<div class="row g-3"><div class="col-12"><label class="form-label">Meta title <span class="counter"><b data-meta-title-count>0</b>/60</span></label><input id="meta-title" name="meta_title" maxlength="60" class="form-control"></div>
<div class="col-12"><label class="form-label">Meta description <span class="counter"><b data-meta-description-count>0</b>/160</span></label><textarea id="meta-description" name="meta_description" maxlength="160" rows="3" class="form-control"></textarea></div>
<div class="col-md-6"><label class="form-label">Keywords</label><input name="meta_keywords" class="form-control" placeholder="Bangladesh, politics"></div><div class="col-md-6"><label class="form-label">Robots</label><select name="meta_robots" class="form-select"><option value="index,follow">index, follow</option><option value="noindex,follow">noindex, follow</option><option value="noindex,nofollow">noindex, nofollow</option></select></div>
<div class="col-md-6"><label class="form-label">Canonical URL</label><input type="url" name="canonical_url" class="form-control"></div><div class="col-md-6"><label class="form-label">Social image</label><input type="file" name="meta_image" class="form-control" accept="image/*"></div>
<div class="col-12"><label class="form-label">Schema markup (JSON-LD)</label><textarea name="schema_markup" rows="4" class="form-control font-monospace" placeholder='{"@@context":"https://schema.org","@@type":"NewsArticle"}'></textarea></div></div>
</div></div></div>
<div class="col-xl-4"><div class="sticky-side">
<div class="card post-card"><div class="card-header"><h5 class="post-heading"><span class="post-step">05</span>Publishing</h5></div><div class="card-body">
<div class="d-flex justify-content-between mb-3"><span class="text-muted">Current state</span><span class="badge bg-warning-transparent text-warning">● Draft</span></div>
<div class="mb-3"><label class="form-label">Status</label><select name="status" class="form-select"><option value="draft">Save as draft</option><option value="review">Send for review</option><option value="scheduled">Schedule</option><option value="published">Publish now</option><option value="archived">Archive</option></select></div>
<div class="mb-3"><label class="form-label">Schedule date & time</label><input type="datetime-local" name="scheduled_at" class="form-control"></div>
<div class="mb-3"><label class="form-label">Author / Reporter</label><select name="author_id" class="form-select"><option value="">Select reporter</option><option>Sumon Mitra</option><option>News Desk</option></select></div>
<div><label class="form-label">Reviewer</label><select name="reviewed_by" class="form-select"><option value="">Assign editor</option><option>Chief Editor</option><option>News Editor</option></select></div><hr>
<div class="switch-row"><span><strong>Allow comments</strong><span class="hint mt-0">Readers can join discussion</span></span><div class="form-check form-switch"><input class="form-check-input" type="checkbox" name="allow_comments" value="1" checked></div></div>
</div></div>
<div class="card post-card"><div class="card-header"><h5 class="post-heading"><span class="post-step">06</span>Classification</h5></div><div class="card-body">
<div class="mb-3"><label class="form-label">Section</label><select name="section_id" class="form-select"><option value="">Select section</option><option>News</option><option>Opinion</option><option>Sports</option></select></div>
<div class="mb-3"><label class="form-label">Category</label><select name="category_id" class="form-select"><option value="">Select category</option><option>National</option><option>Politics</option><option>International</option></select></div>
<div><label class="form-label">Tags</label><select name="tag_ids[]" class="form-select" multiple size="4"><option>Breaking News</option><option>Bangladesh</option><option>Election</option><option>Economy</option></select><span class="hint">Ctrl/Cmd ধরে একাধিক tag নির্বাচন করুন।</span></div>
</div></div><div class="card post-card"><div class="card-header"><h5 class="post-heading"><span class="post-step">07</span>Location</h5></div><div class="card-body">
<div class="mb-3"><label class="form-label">Division</label><select name="division_id" class="form-select"><option value="">All Bangladesh</option><option>Dhaka</option><option>Chattogram</option></select></div>
<div class="mb-3"><label class="form-label">District</label><select name="district_id" class="form-select"><option value="">Select district</option><option>Dhaka</option><option>Cumilla</option></select></div>
<div><label class="form-label">Upazila</label><select name="upazila_id" class="form-select"><option value="">Select upazila</option><option>Sample upazila</option></select></div>
</div></div>
<div class="card post-card"><div class="card-header"><h5 class="post-heading"><span class="post-step">08</span>Display priority</h5></div><div class="card-body">
<div class="switch-row"><span><strong>Breaking news</strong><span class="hint mt-0">Show in breaking ticker</span></span><div class="form-check form-switch"><input class="form-check-input" type="checkbox" name="is_breaking" value="1"></div></div>
<div class="switch-row"><span><strong>Featured story</strong><span class="hint mt-0">Highlight this story</span></span><div class="form-check form-switch"><input class="form-check-input" type="checkbox" name="is_featured" value="1"></div></div>
<div class="switch-row mb-3"><span><strong>Pin story</strong><span class="hint mt-0">Keep above normal stories</span></span><div class="form-check form-switch"><input class="form-check-input" type="checkbox" name="is_pinned" value="1"></div></div>
<label class="form-label">Featured positions</label><div class="placement-grid">
<span class="placement"><input id="home-top" type="checkbox" name="featured_positions[]" value="home_top"><label for="home-top">Home top</label></span>
<span class="placement"><input id="home-middle" type="checkbox" name="featured_positions[]" value="home_middle"><label for="home-middle">Home middle</label></span>
<span class="placement"><input id="category-top" type="checkbox" name="featured_positions[]" value="category_top"><label for="category-top">Category top</label></span>
<span class="placement"><input id="sidebar-place" type="checkbox" name="featured_positions[]" value="sidebar"><label for="sidebar-place">Sidebar</label></span>
</div></div></div>
<div class="card post-card"><div class="card-body"><label class="form-label">News source</label><input name="source" class="form-control" placeholder="Own report / Agency name"><span class="hint">নিজস্ব প্রতিবেদন হলে খালি রাখা যাবে।</span></div></div>
</div></div></div></div>
{{-- Visual-only modal actions; no request is sent yet. --}}
<div class="modal-footer"><span class="me-auto text-muted small"><i class="fe fe-info me-1"></i>Static preview — nothing will be saved yet.</span><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button><button type="button" class="btn btn-outline-primary">Save draft</button><button type="button" class="btn btn-primary"><i class="fe fe-send me-1"></i>Send for review</button></div>
</form></div></div></div>
</div></div></div>
<script>
// Static helpers provide counters/previews only; they never submit the form.
(function($){'use strict';
function slug(v){return v.toString().trim().toLowerCase().replace(/[^\p{L}\p{N}\s-]/gu,'').replace(/[\s_-]+/g,'-').replace(/^-+|-+$/g,'')}
function preview(){var title=$('#post-title').val()||'Your news headline will appear here',s=$('#post-slug').val()||'news-headline',mt=$('#meta-title').val()||title,md=$('#meta-description').val()||$('#post-summary').val()||'Add a concise meta description for search results.';$('[data-title-count]').text($('#post-title').val().length);$('[data-summary-count]').text($('#post-summary').val().length);$('[data-meta-title-count]').text($('#meta-title').val().length);$('[data-meta-description-count]').text($('#meta-description').val().length);$('[data-seo-title]').text(mt);$('[data-seo-slug]').text(s);$('[data-seo-description]').text(md)}
$(document).off('.postStatic')
.on('input.postStatic','#post-title,#post-slug,#post-summary,#meta-title,#meta-description',preview)
.on('click.postStatic','#make-post-slug',function(){$('#post-slug').val(slug($('#post-title').val()));preview()})
.on('input.postStatic','[name="description"]',function(){var w=$(this).val().trim().split(/\s+/).filter(Boolean).length;$('[data-word-count]').text(w);$('[data-read-time]').text((w?Math.max(1,Math.ceil(w/220)):0)+' min')})
.on('change.postStatic','#post-featured-image',function(){var f=this.files&&this.files[0];if(!f)return;var r=new FileReader();r.onload=function(e){$('[data-image-preview]').attr('src',e.target.result).removeClass('d-none');$('[data-upload-text]').addClass('d-none')};r.readAsDataURL(f)})
.on('click.postStatic','#add-gallery',function(){$('#gallery-list').append('<div class="gallery-row"><span class="gallery-icon"><i class="fe fe-image"></i></span><input type="file" name="gallery_images[]" class="form-control form-control-sm" accept="image/*"><input name="gallery_captions[]" class="form-control form-control-sm gallery-caption" placeholder="Caption"><button type="button" class="btn btn-sm btn-outline-danger remove-gallery"><i class="fe fe-trash-2"></i></button></div>')})
.on('click.postStatic','.remove-gallery',function(){if($('#gallery-list .gallery-row').length>1)$(this).closest('.gallery-row').remove()});
preview()
})(jQuery);
</script>